import os
import time
import cffi

ffi = cffi.FFI()
ffi.cdef("""
void *EVP_CIPHER_CTX_new(void);
void EVP_CIPHER_CTX_free(void *);
void *EVP_aes_128_gcm(void);
void *EVP_aes_192_gcm(void);
void *EVP_aes_256_gcm(void);
int EVP_EncryptInit_ex(void *, void *, void *, const unsigned char *, const unsigned char *);
int EVP_EncryptUpdate(void *, unsigned char *, int *, const unsigned char *, int);
int EVP_EncryptFinal_ex(void *, unsigned char *, int *);
int EVP_CIPHER_CTX_ctrl(void *, int, int, void *);
""")

lib = ffi.dlopen("crypto")

EVP_CTRL_GCM_SET_IVLEN = 0x9
EVP_CTRL_GCM_GET_TAG = 0x10

def encrypt(key, nonce, plaintext, aad):
    ctx = lib.EVP_CIPHER_CTX_new()
    if len(key) == 16:
        cipher = lib.EVP_aes_128_gcm()
    elif len(key) == 24:
        cipher = lib.EVP_aes_192_gcm()
    elif len(key) == 32:
        cipher = lib.EVP_aes_256_gcm()

    lib.EVP_EncryptInit_ex(ctx, cipher, ffi.NULL, ffi.NULL, ffi.NULL)
    lib.EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, len(nonce), ffi.NULL)
    lib.EVP_EncryptInit_ex(ctx, ffi.NULL, ffi.NULL, key, nonce)

    outl = ffi.new("int *")
    if aad:
        lib.EVP_EncryptUpdate(ctx, ffi.NULL, outl, aad, len(aad))

    out = ffi.new("unsigned char[]", len(plaintext))
    lib.EVP_EncryptUpdate(ctx, out, outl, plaintext, len(plaintext))

    lib.EVP_EncryptFinal_ex(ctx, ffi.NULL, outl)

    tag = ffi.new("unsigned char[]", 16)
    lib.EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag)

    lib.EVP_CIPHER_CTX_free(ctx)
    return ffi.buffer(out)[:], ffi.buffer(tag)[:]

key = os.urandom(16)
nonce = os.urandom(12)
plaintext = os.urandom(60000 * 1024)
aad = os.urandom(32)

t0 = time.time()
out, tag = encrypt(key, nonce, plaintext, aad)
t1 = time.time()
print(f"cffi libcrypto AESGCM: {t1 - t0}")
